import { LightningElement } from 'lwc';
import GUIDE_URL from '@salesforce/resourceUrl/RLY_Guide_Content';
import REPO_URL from '@salesforce/resourceUrl/RLY_Pipeline_Files';
import IS_ADMIN from '@salesforce/customPermission/RLY_Admin';

const WHO = { gitAdmin: 'Git admin', sfAdmin: 'Salesforce admin', sfUser: 'Salesforce user', gitUser: 'Git user', approver: 'Approver', types: 'Everyone', demo: 'Demo admin' };
const ROLE_ORDER = ['order', 'types', 'sfUser', 'approver', 'gitUser', 'sfAdmin', 'gitAdmin', 'demo'];
const DONE_KEY = 'rlyGuideDone';

const REPO_FILES = [
    { id: 'js', file: 'release-relay.js', where: 'scripts/release-relay.js', what: 'All providers: every step (raise, scan, validate, merge, deploy)', path: '/release-relay.js', save: 'release-relay.js' },
    { id: 'ignore', file: 'forceignore.txt', where: '.forceignore (rename it)', what: 'All providers: keeps profiles and noise out of pull requests', path: '/forceignore.txt', save: 'forceignore.txt' },
    { id: 'gh', file: 'release-relay.yml', where: '.github/workflows/release-relay.yml', what: 'GitHub: the workflow Salesforce starts', path: '/release-relay.yml', save: 'release-relay.yml' },
    { id: 'gl', file: 'release-relay.gitlab-ci.yml', where: 'release-relay.gitlab-ci.yml, included from .gitlab-ci.yml', what: 'GitLab: the job Salesforce starts', path: '/release-relay.gitlab-ci.yml', save: 'release-relay.gitlab-ci.yml' },
    { id: 'bb', file: 'bitbucket-pipelines.yml', where: 'bitbucket-pipelines.yml (merge into yours)', what: 'Bitbucket: the release-relay custom pipeline', path: '/bitbucket-pipelines.yml', save: 'bitbucket-pipelines.yml' },
    { id: 'az', file: 'release-relay.azure-pipelines.yml', where: 'release-relay.azure-pipelines.yml', what: 'Azure DevOps: the pipeline Salesforce runs', path: '/release-relay.azure-pipelines.yml', save: 'release-relay.azure-pipelines.yml' }
];

function loadDone() {
    try {
        return JSON.parse(window.localStorage.getItem(DONE_KEY) || '{}');
    } catch (e) {
        return {};
    }
}

function saveDone(done) {
    try {
        window.localStorage.setItem(DONE_KEY, JSON.stringify(done));
    } catch (e) {
        // Progress is a convenience; the guide works without it.
    }
}

export default class OrgToGitGuide extends LightningElement {
    isAdmin = IS_ADMIN === true;
    content;
    loadError;
    role;
    current = 0;
    done = loadDone();
    showEdit = false;

    guideFileUrl = GUIDE_URL;
    repoZipUrl = REPO_URL;
    repoFiles = REPO_FILES.map((f) => ({ ...f, url: REPO_URL + f.path }));

    connectedCallback() {
        this.role = this.isAdmin ? 'order' : 'sfUser';
        fetch(GUIDE_URL, { credentials: 'same-origin' })
            .then((res) => {
                if (!res.ok) {
                    throw new Error('HTTP ' + res.status);
                }
                return res.json();
            })
            .then((json) => {
                if (!json || !json.roles || !json.setup) {
                    throw new Error('The guide file is missing roles or setup.');
                }
                this.content = json;
            })
            .catch((e) => {
                this.loadError = 'The guide file couldn\'t be read (' + e.message + '). An admin can upload a valid RLY_Guide_Content file in Setup > Static Resources.';
            });
    }

    // ---------- roles ----------

    get loading() { return !this.content && !this.loadError; }
    get ready() { return !!this.content; }
    get version() { return this.content ? this.content.version : ''; }

    get roleButtons() {
        if (!this.content) {
            return [];
        }
        return ROLE_ORDER
            .filter((id) => this.content.roles[id] && (this.isAdmin || !this.content.roles[id].admin))
            .map((id) => ({
                id,
                label: this.content.roles[id].label,
                pressed: id === this.role ? 'true' : 'false',
                cls: 'role-btn role-' + id + (id === this.role ? ' on' : '')
            }));
    }

    get roleInfo() {
        return this.content ? this.content.roles[this.role] : {};
    }

    get isOrder() { return this.role === 'order'; }
    get isGitAdmin() { return this.role === 'gitAdmin'; }
    get notOrder() { return this.role !== 'order'; }

    handleRole(event) {
        this.role = event.currentTarget.dataset.id;
        this.current = 0;
        this.showEdit = false;
    }

    // ---------- steps for the current role ----------

    get rawSteps() {
        if (!this.content) {
            return [];
        }
        const r = this.content.roles[this.role];
        const setup = this.content.setup;
        if (this.role === 'sfAdmin') {
            return setup.filter((s) => s.who === 'sfAdmin' || s.num === 15).concat(r.extra || []);
        }
        if (this.role === 'gitAdmin') {
            return setup.filter((s) => s.who === 'gitAdmin').concat(r.extra || []);
        }
        return r.steps || [];
    }

    get steps() {
        const raw = this.rawSteps;
        const total = raw.filter((s) => s.num !== undefined).length;
        const isSetup = this.role === 'sfAdmin' || this.role === 'gitAdmin';
        return raw.map((s, i) => {
            const key = this.role + ':' + (s.key || s.num || i);
            const isDone = !!this.done[key];
            const cur = i === this.current;
            const numbered = s.num !== undefined;
            return {
                ...s,
                i,
                key,
                numbered,
                dot: isDone ? '✓' : (numbered ? String(s.num) : '•'),
                railCls: 'rail-item' + (cur ? ' current' : '') + (isDone ? ' done' : ''),
                dotCls: 'dot' + (isDone ? ' dot-done' : cur ? ' dot-cur' : ''),
                current: cur ? 'step' : 'false',
                whoLabel: s.who ? WHO[s.who] + (s.also ? ' and ' + WHO[s.also] : '') : WHO[this.role] || '',
                badgeCls: 'badge badge-' + (s.who || this.role),
                ofLabel: numbered ? (isSetup ? 'Step ' + s.num + ' of ' + this.content.setup.length : 'Step ' + s.num + ' of ' + total) : '',
                actionList: (s.actions || []).map((t, n) => ({ id: key + '-' + n, n: n + 1, text: t })),
                tableView: s.table ? {
                    cols: s.table.cols.map((c, n) => ({ id: 'c' + n, text: c })),
                    rows: s.table.rows.map((row, n) => ({ id: 'r' + n, cells: row.map((c, m) => ({ id: 'r' + n + 'c' + m, text: c })) }))
                } : null,
                isDone
            };
        });
    }

    get step() {
        const list = this.steps;
        return list[Math.min(this.current, list.length - 1)] || {};
    }

    get hasSteps() { return this.steps.length > 0; }
    get isLast() { return this.current >= this.steps.length - 1; }
    get isFirst() { return this.current === 0; }

    get progress() {
        const numbered = this.steps.filter((s) => s.numbered);
        const n = numbered.filter((s) => s.isDone).length;
        const pct = numbered.length ? Math.round((n / numbered.length) * 100) : 0;
        return { label: n + ' of ' + numbered.length + ' done', style: 'width: ' + pct + '%' };
    }

    get doneButtonLabel() {
        if (this.step.isDone) {
            return this.isLast ? 'Done' : 'Next';
        }
        return this.isLast ? 'Mark done' : 'Mark done and continue';
    }

    handlePick(event) {
        this.current = Number(event.currentTarget.dataset.index);
        this.scrollToCard();
    }

    handleBack() {
        if (this.current > 0) {
            this.current -= 1;
            this.scrollToCard();
        }
    }

    handleDone() {
        const s = this.step;
        if (s.numbered && !s.isDone) {
            this.done = { ...this.done, [s.key]: true };
            saveDone(this.done);
        }
        if (!this.isLast) {
            this.current += 1;
            this.scrollToCard();
        }
    }

    handleUndo() {
        const copy = { ...this.done };
        delete copy[this.step.key];
        this.done = copy;
        saveDone(copy);
    }

    scrollToCard() {
        const card = this.template.querySelector('.step-card');
        if (card && card.scrollIntoView) {
            card.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
        }
    }

    // ---------- setup order ----------

    get orderRows() {
        if (!this.content) {
            return [];
        }
        const list = this.content.setup;
        return list.map((s, i) => ({
            id: 'o' + s.num,
            num: s.num,
            title: s.title,
            who: WHO[s.who] + (s.also ? ' and ' + WHO[s.also] : ''),
            dotCls: 'tl-dot tl-' + s.who,
            badgeCls: 'badge badge-' + s.who,
            lineCls: i === list.length - 1 ? 'tl-line tl-end' : 'tl-line',
            handoff: s.gives ? 'Handoff: ' + s.gives : '',
            hasHandoff: !!s.gives
        }));
    }

    handleOrderOpen(event) {
        const num = Number(event.currentTarget.dataset.num);
        const s = this.content.setup.find((x) => x.num === num);
        this.role = num === 15 ? 'sfAdmin' : s.who;
        const idx = this.rawSteps.findIndex((x) => x.num === num);
        this.current = Math.max(0, idx);
    }

    // ---------- admin editing ----------

    toggleEdit() {
        this.showEdit = !this.showEdit;
    }

    get editLabel() {
        return this.showEdit ? 'Close' : 'Edit guide';
    }
}
